tsconfig.json:
{
  "compilerOptions": {
    "target": "ES2017",
    "lib": [
      "dom",
      "dom.iterable",
      "esnext"
    ],
    "allowJs": true,
    "skipLibCheck": true,
    "strict": true,
    "noEmit": true,
    "esModuleInterop": true,
    "module": "esnext",
    "moduleResolution": "bundler",
    "resolveJsonModule": true,
    "isolatedModules": true,
    "jsx": "preserve",
    "incremental": true,
    "plugins": [
      {
        "name": "next"
      }
    ],
    "paths": {
      "@/*": [
        "./src/*"
      ]
    }
  },
  "include": [
    "next-env.d.ts",
    "**/*.ts",
    "**/*.tsx",
    ".next/types/**/*.ts"
  ],
  "exclude": [
    "node_modules"
  ]
}

next.config.ts:
import type { NextConfig } from 'next';
const nextConfig: NextConfig = {};
export default nextConfig;

app/globals.css:
@tailwind base;
@tailwind components;
@tailwind utilities;
body { font-family: system-ui, sans-serif; max-width: 800px; margin: 2rem auto; padding: 0 1rem; line-height: 1.6; }

app/layout.tsx:
import type { Metadata } from 'next';
export const metadata: Metadata = { title: { default: 'My Blog', template: '%s | My Blog' }, description: 'A blog about Next.js' };
export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (<html lang="en"><body>{children}</body></html>);
}

app/page.tsx:
import type { Metadata } from 'next';
export const metadata: Metadata = { title: 'Home', description: 'Welcome to my blog' };
export default function Home() { return (<div><h1>Home</h1><p>Check the page title in the browser tab.</p></div>); }

